  M.svg=root.querySelector('svg');M.q=id=>M.svg.querySelector('#'+id);M.units={g:[],f:[]};M.guns=null;M.east=null;M.vb=null;M.trains=[];M.extra=[];M.sp=0;M.spawnIn=1;if(!M.railOn&&M.rail){M.railOn=true;requestAnimationFrame(railTick);}M.cap=root.parentNode.querySelector('.mcap');if(!M.cap){M.cap=document.createElement('div');M.cap.className='mcap';root.parentNode.appendChild(M.cap);}M.hint=null;panInit();phMark();M.ptsKey=null;{const g=M.q('mPts');if(g)M.svg.appendChild(g);}   // 印は、ほかの線や字より上に置く（上に重なった線が、押すのをじゃましないように）
