  for(const u of U){if(u.mg){u.moving=false;if(u.setup>0)u.setup-=dt;continue;}if(u.melee&&u.state!=='rout'){u.moving=false;continue;}   // 白兵戦の間は、その場から動けない
    let tx=u.tx,ty=u.ty,sp=VD.speed;if(u.state==='rout'){tx=u.x;ty=u.side==='g'?Math.min(u.y,VD.refill.y-24*UZ):(u.hit>3?u.y:VD.H-10);sp*=1.3;u.foe=0;}   // ドイツ軍は、後方の線の内がわまで退く
    const d=hyp(tx-u.x,ty-u.y);u.moving=d>1.5;if(!u.moving)continue;let k=1;if(inForest(u.x,u.y))k*=VD.slow.forest;if(riverD(u.x,u.y)<9)k*=VD.slow.river;
    const st=Math.min(d,sp*k*dt);u.x+=(tx-u.x)/d*st;u.y+=(ty-u.y)/d*st;}
