  for(let i=0;i<U.length;i++)for(let j=i+1;j<U.length;j++){const a=U[i],b=U[j];if(a.side!==b.side||!a.dep||!b.dep||a.dep.i!==b.dep.i)continue;const G=(depLen(a)+depLen(b))/2,ds=b.dep.s-a.dep.s,d=Math.abs(ds);if(d>=G)continue;
    const p=(G-d)*.1*(ds>=0?1:-1),TL=trenchLen(a.dep.i);for(const [u,k] of [[a,-1],[b,1]]){const s=cl(u.dep.s+p*k,0,TL),P=trenchPt(u.dep.i,s);u.dep.s=s;u.x=u.tx=P[0];u.y=u.ty=P[1];if(u.post)u.post=[P[0],P[1]];if(u.home&&!u.foe)u.home=[P[0],P[1]];}}
