function setZoom(z,ax,ay){const Z=VD.zoom||[1];z=Math.max(Z[0],Math.min(Z[Z.length-1],z));if(ax===undefined){ax=camX+SW/zoom/2;ay=camY+SH/zoom/2;}camX=ax-(ax-camX)*zoom/z;camY=ay-(ay-camY)*zoom/z;zoom=z;pan(0,0);const b=root.querySelector('.vzl');if(b)b.textContent='×'+(Math.round(z*10)/10);}
function pan(dx,dy){camX=Math.max(0,Math.min(SW-SW/zoom,camX+dx));camY=Math.max(0,Math.min(SH-SH/zoom,camY+dy));}
