const hit=(x,y,side)=>{let b=null,bd=1e9;for(const u of S.units){if(side&&u.side!==side)continue;const [hw,hd]=size(u),fa=u.fa===undefined?Math.PI/2:u.fa,dx=x-u.x,dy=y-u.y,a=Math.abs(-Math.sin(fa)*dx+Math.cos(fa)*dy),d=Math.abs(Math.cos(fa)*dx+Math.sin(fa)*dy);
    if(a<hw+7&&d<hd+9){const q=hyp(dx,dy)-(u.mg?12:0);if(q<bd){bd=q;b=u;}}}return b;};
