  {const ry=VD.refill.y;g.beginPath();g.moveTo(0,0);for(let x=0;x<=VD.W;x+=24){const p=PX(x,ry);g.lineTo(p[0],p[1]);}g.lineTo(VD.W,0);g.closePath();g.fillStyle='rgba(20,23,15,.24)';g.fill();
    g.strokeStyle='#f1d882aa';g.lineWidth=1.5;g.setLineDash([8,6]);g.beginPath();for(let x=0;x<=VD.W;x+=24){const p=PX(x,ry);x?g.lineTo(p[0],p[1]):g.moveTo(p[0],p[1]);}g.stroke();g.setLineDash([]);g.font='700 11px "BIZ UDPGothic",sans-serif';g.textAlign='left';g.fillStyle='#f1d882';g.fillText('後方（この線より北にいる部隊は、補充できる）',10,PX(10,ry)[1]-6);}
