  if(fortIm&&VD.fortImg){const F=VD.fortImg,p=PX(VD.fort[0],VD.fort[1]),w=F.w,h=w*VART.fort.h/VART.fort.w;g.drawImage(fortIm,p[0]-w/2,p[1]-h*F.cy,w,h);}
  // 目標の地点：輪と、おさえている時間
