  $('.bChg').onclick=()=>{if(!S||S.over)return;const n=VSim.charge(S,[...sel]);if(n){snd('whistle',5);say('選んだ部隊が、敵に突っこむ。ふれ合うと、白兵戦になる。');}else say('突っこむ相手が、近くにいない。先に、敵の部隊を押してねらわせる。');};
