const phasePips=k=>`<span class="phz">${(DATA.phases||[]).map((p,i)=>`<span class="pz ${i<k?'on':i===k?'now':''}"><b>${p.year}</b><em>${p.name}</em></span>`).join('')}</span>`;
function hudFit(){const top=$('top');if(!top||typeof G==='undefined'||!G)return;
  document.body.classList.toggle('tw-simple',!detailOn());
  {const mw=document.querySelector('.mapwrap'),P=DATA.phases||[];if(mw&&P.length){let ph=$('phase');if(!ph){ph=document.createElement('div');ph.id='phase';mw.before(ph);}
    const h=`<span class="pl">${DATA.phaseLabel}</span>${phasePips(phaseOf(G.t))}`;if(ph.dataset.h!==h){ph.dataset.h=h;ph.innerHTML=h;}}}
  {const sec=document.querySelector('#army>.sec');if(sec&&!$('bDet')){const b=document.createElement('button');b.id='bDet';b.className='det';b.textContent=detailOn()?'かんたんに':'くわしく';b.onclick=()=>setDetail(!detailOn());sec.appendChild(b);}}let r=$('hres');if(!r){r=document.createElement('div');r.id='hres';top.insertBefore(r,top.querySelector('.hdate'));}
  const pv=preview(G,[UI.mil,UI.dom]),d=(a,b)=>{const v=Math.round(a-b);return v?`<em class="${v>0?'up':'dn'}">${v>0?'＋':'−'}${Math.abs(v)}</em>`:'';};
  const it=[['men','前線の兵士',G.F,'万',''],['fac','軍需工場',G.W,'万',''],['farm','農場',G.A,'万',''],['shell','砲弾の在庫',G.shell,'',pv&&pv.shell!==undefined?d(pv.shell,G.shell):''],['food','食料の備蓄',G.food||0,'',pv&&pv.foodLeft!==undefined?d(pv.foodLeft,G.food||0):''],['flag','国民の戦意',G.morale,'','']];
  r.innerHTML=it.map(([i,l,v,u,e])=>`<div class="rs"><i>${HIC[i]}</i><div><label>${l}</label><b>${Math.round(v)}<small>${u}</small>${e}</b></div></div>`).join('');
  // 労働力の割合を、細い棒で見せる
  // 労働力の割合を、細い棒で見せる。棒をつまんで左右に動かすと、人数が変わる（ふやせるのは、未配置の労働力がある分まで＝うすい色の所まで）
  const tot=(G.F+G.W+G.A+(G.C||0)+(G.pool||0))||1;document.querySelectorAll('#home .box.hrow').forEach((bx,i)=>{const k=bx.dataset.k||['A','W','F'][i];let t=bx.querySelector('.trk');if(!t){t=document.createElement('div');t.className='trk';t.dataset.k=k;t.innerHTML='<u></u><i></i><s></s>';t.title='つまんで左右に動かす';t.tabIndex=0;t.setAttribute('role','slider');t.setAttribute('aria-label',(DATA.sectorName&&DATA.sectorName[k]||'')+'人数。右でふやす、左でへらす');t.addEventListener('keydown',e=>{if(e.key==='ArrowRight'||e.key==='ArrowLeft'){e.preventDefault();stepMove(k,e.key==='ArrowRight'?1:-1);const n=document.querySelector(`.trk[data-k="${k}"]`);if(n)n.focus();}});const rh=bx.querySelector('.rh');bx.insertBefore(t,rh?rh.nextSibling:bx.firstChild);t.addEventListener('pointerdown',e=>trkDown(e,k));}
    const w=(100*G[k]/tot).toFixed(1)+'%';t.children[0].style.width=(100*(G[k]+(G.pool||0))/tot).toFixed(1)+'%';t.children[1].style.width=w;t.children[2].style.left=w;});
  // 左の板の下：将軍と内務大臣の顔と、いまの気分（前の半年の結果から）
  {const home=$('home'),cmd=home&&home.querySelector('.cmd');if(cmd&&window.CHAR_IMG&&!$('adv')){const last=G.log[G.log.length-1],SM=last&&last.staff,LB=DATA.staffMood.label||{},a=document.createElement('div');a.id='adv';
    a.innerHTML=['general','minister'].map(k=>{const m=SM?SM[k].mood:'none';return `<div class="ad ${m}"><canvas data-who="${k}" width="${CHAR_IMG[k].w}" height="${CHAR_IMG[k].h}"></canvas><div><b>${DATA.staff[k]}</b><span>${LB[m]||''}</span></div></div>`;}).join('');home.insertBefore(a,cmd);
    a.querySelectorAll('canvas').forEach(c=>{const k=c.dataset.who,ci=CHAR_IMG[k],im=CHR.im[k+'/idle'],f=Math.min(ci.clips.idle.n-1,k==='general'?20:4),go=()=>c.getContext('2d').drawImage(im,f*ci.w,0,ci.w,ci.h,0,0,ci.w,ci.h);if(im&&im.complete&&im.naturalWidth)go();else if(im)im.addEventListener('load',go,{once:true});});}}
  // 広い画面では、地図を、右の板の左がわの上に寄せて、全体が入る大きさで映す（下の帯に「戦争の代償」と顔を置く）
  const sv=document.querySelector('#smap>svg');if(sv){if(matchMedia('(min-width:1000px)').matches)sv.setAttribute('preserveAspectRatio','xMidYMin slice');else sv.removeAttribute('preserveAspectRatio');}
  // スマホでは、地図を前線のまわりに寄せて映す（画面の向きが変わったときも、ここで合わせなおす）
  if(window.StratMap&&StratMap.refit)StratMap.refit();
  // 地図の凡例：広い画面では、地図の中ではなく、下の帯に1行で出す
  {const home=$('home');if(home&&!$('maplg')){const m=document.createElement('div');m.id='maplg';const per=(DATA.map&&DATA.map.perUnit)||(DATA.band&&DATA.band.perUnit)||60;
    m.innerHTML=`<span><i class="u g"></i>ドイツ軍</span><span><i class="u a"></i>連合軍</span><span class="nt">（兵士2人＝約${per}万人）</span><span><i class="oc"></i>占領した土地</span><span><i class="rl"></i>鉄道</span><span>列車：<i class="sq f"></i>食料 <i class="sq s"></i>砲弾 <i class="sq m"></i>兵士</span>`;const mw=document.querySelector('.mapwrap');if(mw)mw.after(m);else home.appendChild(m);}}}
function settings(){const s=Settings.get(),hasRuby=!!window.RUBY_DIC;
  sheet(`<h2>設定</h2><div class="setrow"><label for="sBgm">音楽の音量</label><input type="range" id="sBgm" min="0" max="100" step="5" value="${Math.round(s.bgm*100)}"></div>
   <div class="setrow"><label for="sSe">効果音の音量</label><input type="range" id="sSe" min="0" max="100" step="5" value="${Math.round(s.se*100)}"></div>
   <div class="setrow"><label>音を鳴らす</label><button id="sOn">${Snd.on?'鳴らす':'鳴らさない'}</button></div>
   <div class="setrow"><label>画面の表示</label><button id="sDet">${detailOn()?'くわしい':'かんたん'}</button></div><p class="note">「くわしい」にすると、生産量と消費量の帯や、方針ごとの細かい見こみが、すべて出る。</p>
   ${hasRuby?`<div class="setrow"><label>ふりがな</label><button id="sRuby">${s.ruby?'つける':'つけない'}</button></div><p class="note">ふりがなは、知らせ・決断・結果・年表などの、文章を読む画面につく。</p>`:''}${closeBtn}`);
  $('sBgm').oninput=e=>Settings.set('bgm',e.target.value/100);$('sSe').oninput=e=>Settings.set('se',e.target.value/100);$('sSe').onchange=()=>Snd.cue('lever');
  $('sOn').onclick=()=>{Snd.set(!Snd.on);settings();};if($('sRuby'))$('sRuby').onclick=()=>{Settings.set('ruby',!s.ruby);settings();};
  $('sDet').onclick=()=>{Settings.set('detail',!detailOn());settings();try{if(G&&!$('game').hidden)draw();}catch(e){}};bindCls();}
// ===== できごとを知る：実際のできごとを、1本の線の上に、起きた順にならべる。下へ動かすと、次のできごとが出てくる =====
function learn(){let L=$('learn');if(!L){L=document.createElement('div');L.id='learn';document.body.appendChild(L);}
  L.innerHTML=`<div class="lhead"><b>第一次世界大戦のできごと</b><span>下へ動かすと、次のできごとが出てくる。</span><button id="bLcls">閉じる</button></div><div class="tl">${DATA.timeline.map(e=>`<article class="tli"><p class="tlw">${e.when}</p><h3>${e.title}</h3>${e.img&&window.ART&&ART[e.img]?`<img src="${ART[e.img]}" alt="" loading="lazy">${e.cap||e.credit?`<p class="tlc">${e.cap?e.cap+'　':''}${e.credit?PCR()+e.credit:''}</p>`:''}`:''}<p>${e.text}</p>${e.game?`<p class="tlg"><b>ゲームの中では</b>　${e.game}</p>`:''}</article>`).join('')}<p class="tlend">年表は、ここまで。</p></div>`;
  L.hidden=false;L.scrollTop=0;$('bLcls').onclick=()=>{L.hidden=true;};Ruby.apply(L);
  const still=window.matchMedia&&matchMedia('(prefers-reduced-motion: reduce)').matches,its=L.querySelectorAll('.tli');
  if(still||!window.IntersectionObserver){its.forEach(x=>x.classList.add('in'));return;}
  const io=new IntersectionObserver(es=>{for(const e of es)if(e.isIntersecting){e.target.classList.add('in');io.unobserve(e.target);}},{root:L,rootMargin:'0px 0px -12% 0px',threshold:.15});its.forEach(x=>io.observe(x));}
// ===== 結果の画面で報告する人の絵。CHAR_IMG に絵があればそれを、なければ仮の絵を出す =====
const FIG={general:'<svg viewBox="0 0 80 110" aria-hidden="true"><path d="M10 110c0-27 13-39 30-39s30 12 30 39z" fill="#6b7265"/><rect x="34" y="60" width="12" height="15" fill="#d8b89a"/><circle cx="40" cy="45" r="17" fill="#e2c4a6"/><path d="M22 41c0-13 8-21 18-21s18 8 18 21c-7-4-29-4-36 0z" fill="#3c4238"/><path d="M38 21l2-13 2 13z" fill="#c9a64d"/><path d="M29 55q11 6 22 0" stroke="#8a7460" stroke-width="3.5" fill="none"/><rect x="12" y="79" width="13" height="5" fill="#c9a64d"/><rect x="55" y="79" width="13" height="5" fill="#c9a64d"/><circle cx="40" cy="88" r="2" fill="#c9a64d"/><circle cx="40" cy="98" r="2" fill="#c9a64d"/></svg>',
  minister:'<svg viewBox="0 0 80 110" aria-hidden="true"><path d="M10 110c0-27 13-39 30-39s30 12 30 39z" fill="#26262b"/><path d="M33 72l7 16 7-16z" fill="#f3efe6"/><path d="M38.5 76h3l1.5 14-3 4-3-4z" fill="#5a2a2a"/><rect x="34" y="60" width="12" height="14" fill="#d8b89a"/><circle cx="40" cy="45" r="17" fill="#e6caae"/><path d="M23 41c1-11 8-18 17-18s16 7 17 18c-3-6-31-6-34 0z" fill="#b9b4aa"/><circle cx="33" cy="46" r="5" fill="none" stroke="#333" stroke-width="1.4"/><circle cx="47" cy="46" r="5" fill="none" stroke="#333" stroke-width="1.4"/><path d="M38 46h4" stroke="#333" stroke-width="1.4"/><path d="M33 57q7 4 14 0" stroke="#9a9388" stroke-width="3" fill="none"/></svg>'};
// 絵は、動きごとに横に並べたこま送り（CHAR_IMG[k].clips）。気分（mood）ごとの動かし方は CHAR_IMG[k].moods に入っている
//   moods の1行＝[動きの名前, はじめのこま, 終わりのこま, 'pp'（行って戻る）, 回数]。回数のない 'pp' は、そこでくり返し続ける。最後まで行ったら、はじめに戻る
const CHR={im:{},timer:0};
function chrLoad(){const C=window.CHAR_IMG;if(!C)return;for(const k in C)for(const n in C[k].clips||{}){const im=new Image();im.src=C[k].clips[n].src;if(im.decode)im.decode().catch(()=>{});CHR.im[k+'/'+n]=im;}}
function chrSeq(prog){const q=[];let loop=0;for(const [clip,a,b,flag,n] of prog){const d=b>=a?1:-1,go=[],back=[];for(let f=a;f!==b+d;f+=d)go.push([clip,f]);for(let f=b-d;f!==a;f-=d)back.push([clip,f]);
    if(flag!=='pp'){q.push(...go);continue;}if(!n){loop=q.length;q.push(...go,...back);return {q,loop};}for(let r=0;r<n;r++)q.push(...go,...back);q.push([clip,a]);}return {q,loop};}
const figure=(k,mood)=>{const c=window.CHAR_IMG&&CHAR_IMG[k];return c&&c.clips?`<canvas class="chr anim" data-who="${k}" data-mood="${mood||'idle'}" width="${c.w}" height="${c.h}" role="img" aria-label="${DATA.staff[k]}"></canvas>`:`<div class="chr draft">${FIG[k]}</div>`;};
function chrPlay(){clearInterval(CHR.timer);const still=window.matchMedia&&matchMedia('(prefers-reduced-motion:reduce)').matches;
  const A=[...document.querySelectorAll('canvas.chr.anim')].map(el=>{const k=el.dataset.who,c=CHAR_IMG[k],s=chrSeq(c.moods[el.dataset.mood]||c.moods.idle);return {el,k,c,g:el.getContext('2d'),q:s.q,loop:s.loop,i:still?Math.floor(s.q.length*.6):0};});if(!A.length)return;
  const paint=a=>{const [clip,f]=a.q[a.i],im=CHR.im[a.k+'/'+clip];if(!im||!im.complete||!im.naturalWidth)return;a.g.clearRect(0,0,a.c.w,a.c.h);a.g.drawImage(im,f*a.c.w,0,a.c.w,a.c.h,0,0,a.c.w,a.c.h);};
  A.forEach(paint);if(still)return;
  CHR.timer=setInterval(()=>{if(!A[0].el.isConnected){clearInterval(CHR.timer);return;}for(const a of A){a.i++;if(a.i>=a.q.length)a.i=a.loop;paint(a);}},1000/(A[0].c.fps||8));}
const report=(k,L,d0,mood,view)=>L.length?`<div class="rep"><div class="repfig">${figure(k,mood)}<b>${DATA.staff[k]}</b></div><div class="bubs"><p class="bub" style="animation-delay:${d0.toFixed(2)}s">${L.map(x=>`<span>${x}</span>`).join('')}${view?`<span class="view"><b>見立て</b>　${view}</span>`:''}</p></div></div>`:'';
// 実施した政策のカード：絵（なければ名前だけ）の上に、「実施」のスタンプをおす
