function nextTurn(){UI={post:'def',mil:null,dom:null,F0:G.F};draw();if(window.Bgm){Bgm.duck(1);Bgm.play(DATA.music.byYear[DATA.turns[G.t].id.slice(0,4)]);}if(window.Snd&&G.t>0)setTimeout(()=>{if(!$('block')||$('block').hidden)Snd.cue('far');},1800);news(()=>{const T=DATA.turns[G.t];if(T.east&&window.StratMap&&StratMap.east)StratMap.east(T.east);if(G.t===0&&!tourSeen)tour(0);if(G.t>0)pickFlow();});}
