// 死傷者の見こみを、言葉にする（少ない・多い・非常に多い）
function casWord(v,plain){for(const [max,w,cls] of DATA.words.cas)if(v<max)return plain?w:`<span class="${cls}">${w}</span>`;return '';}
// 半年ごとの決断：知らせと3つの選択肢を出す。選ぶと、結果の文を出す。どの選択肢で何が変わるかは、選ぶ前には見せない
function eventSheet(i,then){const ev=DATA.events&&DATA.events[i];if(!ev){then();return;}if(window.Snd)Snd.cue('telegram');
  sheet(`<h2>決断　${ev.title}</h2><p class="note">${ev.when}</p>${window.ART&&ART['ev'+i]?`<img class="evim" src="${ART['ev'+i]}" alt="">`:''}<p class="nw">${ev.text}</p><p class="nw dem"><b>${ev.ask}</b><br><span class="note">3つのうち1つを選ぶ。選んだ結果は、国民の戦意や、食料・砲弾・兵士の数にあらわれる。</span></p>
   <div class="pols">${ev.opts.map((o,k)=>`<button class="pol ev" data-ev="${k}"><b>${'①②③④'[k]}　${o.text}</b></button>`).join('')}</div>`);
  document.querySelectorAll('[data-ev]').forEach(b=>b.onclick=()=>{const k=+b.dataset.ev,o=applyEvent(G,i,k);draw();
    sheet(`<h2>決断　${ev.title}</h2><p class="note">あなたの決断</p><p class="nw"><b>${'①②③④'[k]}　${o.text}</b></p><p class="nw dem">${o.out}</p><div class="go"><button class="main" id="bEv">次の半年へ</button></div>`);$('bEv').onclick=()=>{$('veil').hidden=true;then();};});}
// アメリカの国旗（1912〜1959年のもの：星は48こ）
const US_FLAG=(()=>{let st='';for(let r=0;r<6;r++)for(let c=0;c<8;c++)st+=`<use href="#usst" x="${(6.2+c*12.35).toFixed(1)}" y="${(5.8+r*11.67).toFixed(1)}"/>`;
  return `<svg class="usflag" viewBox="0 0 247 130" role="img" aria-label="アメリカの国旗"><defs><path id="usst" d="M0,-3.2L.75,-1.03L3.04,-.99L1.21,.39L1.88,2.59L0,1.28L-1.88,2.59L-1.21,.39L-3.04,-.99L-.75,-1.03Z" fill="#fff"/></defs><rect width="247" height="130" fill="#b22234"/>${[1,3,5,7,9,11].map(i=>`<rect y="${i*10}" width="247" height="10" fill="#fff"/>`).join('')}<rect width="98.8" height="70" fill="#3c3b6e"/>${st}</svg>`;})();
// 人の印をならべる：1つ＝10万人（DATA.picPer）。m＝ドイツ人の男性（黄）、w＝女性（赤）、p＝捕虜・占領地の住民（灰）、e＝敵（青）。「n」がつくと、これから加わる分（うすく出す）
const pics=L=>`<span class="pic">${L.map(([cls,v])=>('<i class="'+cls+'"></i>').repeat(Math.max(0,Math.round(v/DATA.picPer)))).join('')}</span>`;
// 農場（A）・工場（W）で働く人の内わけ。女性と、捕虜・占領地の住民は、政策で加わる。レバーでは動かせず、兵士にもなれない
const comp=k=>{const L=[['m',G[k]]];for(const [id,cls] of [['women','w'],['forced','p']]){const v=P(id)[k]||0;if(!v)continue;if(G.done[id])L.push([cls,v]);else if(UI.dom===id)L.push([cls+' n',v]);}return L;};
// 結果の画面：この半年の死傷者を、人の印（1つ＝DATA.toll.per 人）で、左上から順にならべる。ならび終わったら、戦死（黒）・負傷（赤）・捕虜（灰）に色を分ける
function tollDraw(cas,dead){const cv=$('tollCv'),lg=$('tollLg');if(!cv)return;const per=DATA.toll.per,n=Math.max(1,Math.round(cas*10000/per)),nd=Math.min(n,Math.round(dead*10000/per)),np=Math.min(n-nd,Math.round(cas*DATA.split.pow*10000/per)),nw=n-nd-np;
  const cw=7,ch=12,cols=Math.max(10,Math.floor(cv.parentNode.clientWidth/cw)),rows=Math.ceil(n/cols),dpr=Math.min(2,window.devicePixelRatio||1);cv.width=cols*cw*dpr;cv.height=rows*ch*dpr;cv.style.width=cols*cw+'px';cv.style.height=rows*ch+'px';const c=cv.getContext('2d');c.scale(dpr,dpr);
  const one=(i,col)=>{const x=(i%cols)*cw,y=Math.floor(i/cols)*ch;c.clearRect(x,y,cw,ch);c.fillStyle=col;c.beginPath();c.arc(x+3,y+2.3,2,0,6.283);c.fill();c.beginPath();c.moveTo(x+.8,y+11);c.lineTo(x+.8,y+7);c.arc(x+3,y+7,2.2,Math.PI,0);c.lineTo(x+5.2,y+11);c.fill();};
  const C0='#b08a2a',col=i=>i<nd?'#16130f':i<nd+nw?'#b3352b':'#8b8b86',man=v=>v>=10000?`${Math.round(v/1000)/10}万人`:`${v}人`;
  const legend=()=>{lg.innerHTML=`<span><i style="background:#16130f"></i>戦死 ${man(nd*per)}</span><span><i style="background:#b3352b"></i>負傷 ${man(nw*per)}</span><span><i style="background:#8b8b86"></i>捕虜 ${man(np*per)}</span><span class="note">印1つ＝${per}人</span>`;if(window.Snd)Snd.cue('toll');};
  if(window.matchMedia&&matchMedia('(prefers-reduced-motion: reduce)').matches){for(let i=0;i<n;i++)one(i,col(i));legend();return;}
  let done=0,t0=0;const d1=Math.min(2800,900+n*1.1),d2=1200;lg.innerHTML=`<span class="note">印1つ＝${per}人</span>`;
  const p1=now=>{if(!cv.isConnected)return;if(!t0)t0=now;const u=Math.min(1,(now-t0)/d1),k=Math.round(n*u);for(;done<k;done++)one(done,C0);if(u<1)requestAnimationFrame(p1);else setTimeout(()=>{done=0;t0=0;legend();requestAnimationFrame(p2);},600);};
  const p2=now=>{if(!cv.isConnected)return;if(!t0)t0=now;const u=Math.min(1,(now-t0)/d2),k=Math.round(n*u);for(;done<k;done++)one(done,col(done));if(u<1)requestAnimationFrame(p2);};requestAnimationFrame(p1);}
// アメリカが参戦したことを、大きな国旗で知らせる
function usSheet(then){if(window.Snd)Snd.cue('telegram');const u=DATA.usEntry;sheet(`<h2>${u.title}</h2>${US_FLAG}<p class="nw dem"><b>${u.text}</b></p><div class="go"><button class="main" id="bUs">この半年の結果を見る</button></div>`);$('bUs').onclick=then;}
function alertsNow(){const a=[],dm=DATA.turns[G.t].demand;if(dm)a.push(`${dm.who}が、攻勢を求めている。`);if(usIn(G))a.push('アメリカ軍が、毎月つぎつぎとヨーロッパに着いている。');else if(G.ubAt>=0)a.push('アメリカが参戦した。アメリカ軍が、海をわたりはじめている。');
  if(G.gasAt>=0&&G.t>=G.gasAt+P('gas').gasTurns)a.push('敵も毒ガスを使っている。');if(G.morale<35)a.push('町でストライキとデモが広がっている。');
  if(G.pos<=DATA.collapse*.6)a.push(`前線が大きく下がっている。あと${Math.max(0,G.pos-DATA.collapse).toFixed(0)}km下がると、軍がくずれる。`);return a;}
function news(then){const T=DATA.turns[G.t];if(window.Snd)Snd.cue(T.demand?'telegram':'news');const np=DATA.policies.filter(p=>p.from===G.t&&policyOK(G,p));
  const pk=phaseOf(G.t),ph=(DATA.phases||[])[pk],phNew=ph&&(G.t===0||phaseOf(G.t-1)!==pk);
  sheet(`${ph?`<div class="nphase">${phasePips(pk)}</div>`:''}<h2>${T.id}　${T.head}</h2>${T.news.map(x=>`<p class="nw">${x}</p>`).join('')}${phNew?`<p class="nw real"><b>${DATA.phaseReal}</b>　${ph.real}</p>`:''}${T.east?`<p class="nw"><b>東部戦線から${T.east}万人が、前線に加わる。</b></p>`:''}${drawOpen(G)?`<p class="nw">${DATA.peace.draw.news}</p>`:''}${T.demand?`<p class="nw dem"><b>${T.demand.text}</b><br><span class="note">求めにこたえて攻めるか、そむいて守るかは、あなたが決める。そむけば、国民の戦意が下がる。</span></p>`:''}
   ${alertsNow().map(a=>`<div class="alert">${a}</div>`).join('')}${(pn=>pn.length?`<p class="note ptn"><i class="ptm"></i>${DATA.map.pointText.news}：${pn.map(p=>p.e.title).join('／')}</p>`:'')(pointsNow().filter(p=>p.from===G.t))}${np.length?`<p class="note">新しく選べる政策：${np.map(p=>p.name).join('／')}</p>`:''}
   <div class="go"><button class="main" id="bRead">${G.t===0?'戦争を始める':'この半年の方針を決める'}</button></div>`);
  $('bRead').onclick=()=>{$('veil').hidden=true;if(typeof then==='function')then();};}
// 絵文字のかわりに使う小さな絵：人（1人＝50万人）と、国内の4つの分野
