  const fcP=fc[UI.post],useS=Math.min(pv.stock,fcP.need),lackS=fcP.need-useS,lackF=pv.foodNeed-pv.foodStock-pv.foodMade,R0=Math.round;
  $('top').innerHTML=`<div class="hname"><h1>総力戦 1914</h1><span class="role">ドイツ帝国　戦争指導部</span></div>
   <div class="hdate"><b>${T.id}<span>${T.head}</span></b><div class="row"><span class="pips">${DATA.turns.map((_,i)=>`<i class="${i<G.t?'on':i===G.t?'now':''}"></i>`).join('')}</span>${G.t+1}回目／${n}回</div></div>
   <div class="htoll" id="toll"><label>戦争の代償</label><span>戦死した兵士<b>${man(G.dead)}</b></span><span>負傷・捕虜<b>${man(G.hurt)}</b></span><span title="飢えと病気で死んだ市民">市民の死者<b>${man(G.civil)}</b></span><span>送った兵士<b>${man(G.sent+Math.max(0,G.F-UI.F0))}</b></span><span>戦費<b>${R0(G.debt)}億マルク</b></span></div>
   <button class="again" id="bSet">設定</button><button class="again" id="bHelp">使い方</button><button class="again" id="bNews">知らせを読む</button><button class="again" id="bLearn">できごとを知る</button>`;
  // 上からの求めが指す所の、小さな窓（地図の右下）
  {const sp=T.demand&&T.demand.spot,w=$('spotwin');if(w){const on=!!(sp&&sp.win);w.hidden=!on;w.parentNode.classList.toggle('haswin',on);
    // 絵（SPOT_IMG）は、立体モデルを少しずつ回して書き出したこまを、順に見せる。絵がまだないときは、仮の絵を出す。同じ回の間は、作り直さない（回る動きがとぎれないように）
    const key=on?G.t+'|'+sp.win.img:'';if(on&&w.dataset.key!==key){const im=window.SPOT_IMG&&SPOT_IMG[sp.win.img];
      w.innerHTML=`<h4>${sp.win.title}</h4><div class="pic">${im?`<div class="turn" role="img" aria-label="${sp.win.title}の模型" style="aspect-ratio:${im.w}/${im.h};background-image:url(${im.src});background-size:${im.frames*100}% 100%;--end:${(100*im.frames/(im.frames-1)).toFixed(4)}%;animation:spotspin ${im.sec||10}s steps(${im.frames}) infinite"></div>`:SPOT_DRAFT}</div><p>${sp.win.text}</p>`;}
    w.dataset.key=key;}}
  const al=alertsNow();if(fr<.9)al.push(`食料が足りない（備蓄を合わせても、必要な量の${pct(fr)}）。`);$('alerts').innerHTML=al.map(a=>`<div class="alert">${a}</div>`).join('');
  // 前線の方針：3つを、同じ項目の表でくらべる
  const row=k=>{const Q=DATA.posture[k],f=fc[k],net=f.gain-f.ctr,dm=T.demand?(T.demand.post.includes(k)?'<i class="dmk y" title="求めにこたえる">●</i>':'<i class="dmk n" title="求めにそむく">●</i>'):'';
    // 見こみは、数字ではなく言葉で出す（区切りは DATA.words）
    const mv=DATA.words.move,fl=f.open?'<b class="okk">▲▲ 大前進</b>':(net>mv?'<b class="okk">▲ 進む</b>':'')+(f.back>.5?'<b class="lack">▼ 下がる</b>':(net>mv?'':'― 変わらず'));
    return `<button class="opt prow ${UI.post===k?'on':''}" data-post="${k}"><b>${dm}${Q.name}</b><span class="${f.sr<.995?'lack':'okk'}">${f.sr<.995?'<i class="sx">不足 </i>'+pct(f.sr):'足りる'}</span>${casWord(f.cas)}${casWord(f.eCas)}<span class="fl">${fl}</span><span class="${f.dm<-8?'lack':''}">${sgn(Math.round(f.dm))}</span></button>`;};
  const pk=(kind,label)=>{const p=UI[kind]&&P(UI[kind]);const any=DATA.policies.some(q=>q.kind===kind&&policyOK(G,q));
    return `<button class="pick ${p?'on':''}" data-pick="${kind}" ${any?'':'disabled'}><b>${label}</b><span>${p?p.name:(any?'選ぶ（1回に1つ）':'まだない')}</span></button>`;};
  $('army').innerHTML=`<div class="sec">前線の方針</div><div class="ptab"><div class="prow ph"><span></span><span>砲弾</span><span>死傷者</span><span>敵の死傷</span><span>前線</span><span>戦意</span></div>${Object.keys(DATA.posture).map(row).join('')}</div>
   ${T.demand?`<div class="dnote">${T.demand.who}の求め：攻勢か大攻勢。<i class="dmk y">●</i>こたえる　<i class="dmk n">●</i>そむく</div>`:''}
   <div class="picks">${pk('mil','軍事政策')}${pk('dom','国内政策')}</div>`;
  // 人を置く：それぞれ、作る物が足りるかどうかを帯のグラフで出す
  const fMax=Math.max(pv.foodNeed*1.35,(pv.foodStock+pv.foodMade)*1.04),sNeed=Object.keys(fc).map(k=>fc[k].need),sMax=Math.max(Math.max(...sNeed)*1.08,pv.stock*1.04);
  const fLeft=lackF>.5?0:pv.foodLeft,sLeft=pv.stock-useS,fDiff=pv.foodStock+pv.foodMade-pv.foodNeed,sDiff=pv.made-useS-lackS;
