  const lw=(DATA.life.words.find(w=>pv.life<w[0])||DATA.life.words[DATA.life.words.length-1]),lifeOut=`<span class="out life ${pv.lifeM<-.5?'bad':''}"><span class="ob"><span class="oh">国民の生活 <b class="${lw[2]}">${lw[1]}</b>${pv.lifeM<-.5?`<b class="bdg bad">戦意 ${sgn(Math.round(pv.lifeM))}</b>`:'<b class="bdg ok">足りている</b>'}</span><span class="lnote">鉱山・鉄道・商店など。へらしすぎると、国民の生活が苦しくなる。</span></span></span>`;
  const badge=(short,lack,d,unit)=>lack>.5?`<b class="bdg bad">不足 −${R0(lack)}</b>`:`<b class="bdg ${d>=0?'ok':'dn'}">${d>=0?'ふえる':'へる'} ${sgn(R0(d))}</b>`;
  const foodOut=`<span class="out ${lackF>.5?'bad':''}">${ICON.bread}<span class="ob"><span class="oh">食料の備蓄 <b>${R0(pv.foodStock)}</b> → 半年後 <b>${R0(fLeft)}</b>${badge('f',lackF,fLeft-pv.foodStock)}</span>
    ${balance({stock:pv.foodStock,made:pv.foodMade,need:pv.foodNeed,max:fMax,lIn:['備蓄','生産量'],lOut:'消費量'})}</span>${spark([DATA.start.food||0].concat(G.log.map(r=>r.food)),fLeft)}</span>`;
  const shellOut=`<span class="out ${lackS>.5?'bad':''}">${ICON.shell}<span class="ob"><span class="oh">砲弾の在庫 <b>${R0(pv.shell0)}</b> → 半年後 <b>${R0(sLeft)}</b>万発${badge('s',lackS,sLeft-pv.shell0)}</span>
    ${balance({stock:pv.shell0,made:pv.made,need:fcP.need,max:sMax,lIn:['在庫','生産量'],lOut:'消費量',marks:Object.keys(fc).map(k=>({v:fc[k].need,label:DATA.posture[k].name.charAt(0),cls:k===UI.post?'on':'dim'}))})}</span>${spark([DATA.start.shell].concat(G.log.map(r=>r.shell)),sLeft)}</span>`;
  const ratio=pv.E/Math.max(1,pv.F),lossF=fcP.cas*(DATA.split.dead+DATA.split.lost),fAfter=Math.max(0,pv.F-lossF),tot=pv.F+pv.E,frontOut=`<span class="out"><span class="ob">
    <span class="vsp"><em>敵 約${Math.round(pv.E/10)*10}万人（味方の${ratio.toFixed(1)}倍）</em>${pics([['e',pv.E]])}</span></span></span>`;
  const mAfter=clamp(mp+fcP.dm,0,100),lo=Math.min(mp,mAfter),pa=DATA.peace.acceptBelow;
  const rowBox=(k,icon,name,v,extra,out,pic)=>`<div class="box hrow ${k==='F'?'front':''}" data-k="${k}"><div class="rh"><b>${icon}${name}</b><span class="n">${R0(v)}<small>万人</small></span>${extra?`<span class="eff">${extra}</span>`:''}${lever(k,name)}</div>${pic||''}${out}</div>`;
  $('home').innerHTML=`<div class="sec">労働力の配分<span class="pool ${G.pool?'has':''}" id="pool">未配置の労働力 <b>${G.pool}</b>万人${G.pool?pics([['m',G.pool]]):''}</span></div>
   <div class="piclg"><span><i class="m"></i>ドイツ人の男性</span><span><i class="w"></i>女性</span><span><i class="p"></i>捕虜・占領地の住民</span><span>印1つ＝${DATA.picPer}万人</span></div>
   ${rowBox('A',ICON.A,'農場',G.A,pv.A?`＋${pv.A}`:'',foodOut,pics(comp('A')))}${rowBox('C',ICON.C,'そのほかの仕事',G.C||0,pv.C?`＋${pv.C}`:'',lifeOut,pics(comp('C')))}${rowBox('W',ICON.W,'軍需工場',G.W,pv.W?`＋${pv.W}`:'',shellOut,pics(comp('W')))}${rowBox('F',ICON.F,'前線の兵士',G.F,addF?`＋${addF}`:'',frontOut,pics([['m',G.F],['m n',addF]]))}
   <div class="box" data-k="M"><div class="rh"><b>${ICON.M}国民の戦意</b><span class="n">${R0(mp)}<small>／100</small></span><span class="eff">半年後 <b class="${mAfter<35?'lack':''}">約${R0(mAfter)}</b></span></div>
    ${gauge(100,[{v:lo,cls:lo<35?'bad':'ok'},{v:Math.abs(mAfter-mp),cls:mAfter<mp?'loss':'gain'}],[{v:pa,label:`${pa}より下で講和できる`,cls:'dim'}])}
    <span class="eq">${fcP.parts.map(p=>`<span class="chip ${p[1]<0?'m':'p'}">${p[0]} ${sgn(Math.round(p[1]))}</span>`).join('')}</span></div>
   <div class="cmd"><button class="main" id="bGo">この半年を進める</button>${G.t>=DATA.peace.from?'<button class="sub" id="bPeace">講和をさぐる</button>':''}</div>`;
  levBind();
  document.querySelectorAll('[data-post]').forEach(b=>b.onclick=()=>{UI.post=b.dataset.post;draw();});
