function peace(){const tm=peaceTerms(G),ok=canAccept(G,tm);
  sheet(`<h2>講和をさぐる</h2>${tm==='draw'?`<p>中立国を通じて、連合国に講和を打診した。</p><p class="big">フランスとイギリスの答え：<b>「占領地を返し、国境を戦争の前にもどすなら、応じる。賠償金は求めない。」</b></p>`
   :`<p>中立国を通じて、連合国に講和を打診した。</p><p class="big">連合国の出した条件</p><ul>${DATA.harshTerms.map(x=>`<li>${x}</li>`).join('')}</ul>
     ${ok?'<p>国民は戦争につかれている。この条件でも、受け入れることはできる。</p>':`<p><b>軍と議会が反対している。「これまでの犠牲をむだにするのか。」</b><br>国民の戦意が${DATA.peace.acceptBelow}より下がるまで、この条件では講和を結べない（いまは${Math.round(G.morale)}）。</p>`}`}
   <div class="go">${ok?'<button class="main" id="bYes">この条件で講和を結ぶ</button>':''}<button id="bNo">戦争を続ける</button></div>`);
  $('bNo').onclick=()=>{$('veil').hidden=true;};if($('bYes'))$('bYes').onclick=()=>{G.sent+=Math.max(0,G.F-UI.F0);UI.F0=G.F;makePeace(G);$('veil').hidden=true;epilogue(endScreen);};}
// 終わりのふり返り：黒い画面に、この戦争であなたが決めたことと、その結果を、1行ずつ出す（DATA.epilogue）。「先へ進む」で、いつでも最後の画面へ
function epilogue(then){const E=DATA.epilogue;if(!E){then();return;}const man0=v=>Math.round(v)+'万人',L=[E.open];
  for(const R of G.log){const when=R.id.replace(/\s+/g,'')+'、';for(const id of R.pols)if(E.pol[id]&&!L.some(x=>x.endsWith(E.pol[id])))L.push(when+E.pol[id]);if(R.battle)L.push(when+E.battle[R.battle.mode+(R.battle.win?'Win':'Lose')]);}
  const v={sent:man0(G.sent),dead:man0(G.dead),hurt:man0(G.hurt),civil:man0(G.civil)};for(const s of E.sum){if(s.includes('{civil}')&&G.civil<.5)continue;L.push(s.replace(/\{(\w+)\}/g,(m,k)=>v[k]));}
  {const tt=DATA.ends[G.over.type].title;L.push((/^[0-9０-９]/.test(tt)?'':G.over.at.replace(/\s+/g,'')+'、')+tt+'。',E.last);}
  if(window.Snd)Snd.stopAll(.6);if(window.Bgm){Bgm.duck(1);Bgm.play(DATA.music.end);}
  const w=document.createElement('div');w.id='epi';w.innerHTML=`<div class="epibg" style="${window.ART&&ART.title?`background-image:url(${ART.title})`:''}"></div><div class="epil"></div><button class="epis">${E.skip}</button>`;document.body.appendChild(w);
  const box=w.querySelector('.epil');let i=0,tm=0,done=false;const fin=()=>{if(done)return;done=true;clearTimeout(tm);w.remove();then();};w.querySelector('.epis').onclick=fin;
  const step=()=>{if(done)return;if(i>=L.length){w.querySelector('.epis').classList.add('end');return;}const p=document.createElement('p');p.textContent=L[i++];if(i===L.length)p.className='last';box.appendChild(p);Ruby.apply(p);box.scrollTop=box.scrollHeight;tm=setTimeout(step,(E.sec||2.6)*1000);};step();}
function endScreen(){const e=DATA.ends[G.over.type],r=DATA.real;if(window.Snd){Snd.stopAll(.4);Snd.cue('end_'+G.over.type);}if(window.Bgm){Bgm.duck(1);Bgm.play(DATA.music.end);}const I=window.TW_FACES||[];show(false);
  const rows=[['前線へ送った兵士',man(G.sent),r.sent],['戦死した兵士',man(G.dead),r.dead],['負傷した兵士・捕虜',man(G.hurt),r.hurt],['飢えと病気で死んだ市民',man(G.civil),r.civil],['戦費',Math.round(G.debt)+'億マルク',r.debt],['戦争の終わり方',`${G.over.at}　${e.title}`,r.end]];
  $('screen').innerHTML=`<div class="top"><h1>総力戦 1914</h1><span class="when">${G.over.at}　${e.title}</span></div>
  <div class="page"><p style="font-family:var(--min);font-size:17px">${e.text}</p>
   <h2>あなたの戦争と、実際のドイツ</h2><div class="tw"><table><tr><th></th><th>あなた</th><th>実際のドイツ（1914〜1918年）</th></tr>${rows.map(x=>`<tr><th>${x[0]}</th><td class="num">${x[1]}</td><td>${x[2]}</td></tr>`).join('')}</table></div>
   <h2>半年ごとの記録</h2><div class="tw"><table><tr><th>時期</th><th>前線の方針</th><th>政策</th><th>死傷者</th><th>前線</th><th>食料</th><th>戦意</th></tr>
   ${G.log.map(R=>`<tr><td>${R.id}</td><td>${DATA.posture[R.post].name}</td><td>${R.pols.map(id=>P(id).name).join('、')||'—'}</td><td class="num">${Math.round(R.cas)}万人</td><td class="num">${R.open?`＋${Math.round(R.open.fin)}km`:`${(R.gain-R.back)>=0?'＋':'−'}${Math.abs(R.gain-R.back).toFixed(1)}km`}</td><td class="num">${pct(R.fr)}</td><td class="num">${R.dm>=0?'＋':'−'}${Math.abs(Math.round(R.dm))}</td></tr>`).join('')}</table></div>
   ${(G.picks||[]).length?`<h2>あなたの決断</h2><div class="tw"><table><tr><th>時期</th><th>できごと</th><th>あなたの決断</th></tr>${G.picks.map(p=>{const ev=DATA.events[p.i];return `<tr><td>${ev.when}</td><td>${ev.title}</td><td>${ev.opts[p.k].text}</td></tr>`;}).join('')}</table></div>`:''}
   ${(DATA.after||[]).map(a=>`<h2 class="rd">${a.title}</h2><div class="lead aft">${photo(a)}<p>${a.text}</p>${a.src?`<p class="src">${a.src}</p>`:''}</div>`).join('')}
   <h2 class="rd">${DATA.bridgeHead||'この後の授業では'}</h2><div class="lead">${[].concat(DATA.bridge).map(x=>`<p>${x}</p>`).join('')}</div>
   <h2 class="rd">考えること</h2><ol class="qs">${DATA.questions.map(q=>`<li>${q}</li>`).join('')}</ol>
   <div class="go"><button class="main" id="bAgain">もう一度、最初から</button></div>${credits()}</div>`;
  $('bAgain').onclick=startScreen;window.scrollTo(0,0);Ruby.apply($('screen'));}
// 前線の帯（front.js）は後から読みこまれるので、読みこみが終わってから最初の画面を出す
{const draw0=draw;draw=function(){try{const s=DATA.step,q=(G.pool||0)-Math.round((G.pool||0)/s)*s;if(Math.abs(q)>1e-9){G.pool-=q;G.F+=q;}}catch(e){}   // 未配置の労働力に端数が残っていたら、前線の兵士にもどす
  const r=draw0.apply(this,arguments);try{hudFit();}catch(e){}return r;};}
let booted=false;const boot=()=>{if(booted)return;booted=true;chrLoad();startScreen();window.addEventListener('resize',()=>{if($('game'))hudFit();});};
if(document.readyState==='complete')boot();else window.addEventListener('load',boot);
